/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --primary: #0051C3;
  --primary-dark: #003d94;
  --primary-light: #e8f0fe;
  --accent: #DE5052;
  --accent-dark: #b83a3c;
  --white: #FFFFFF;
  --dark: #0f172a;
  --gray-900: #1e293b;
  --gray-700: #334155;
  --gray-500: #64748b;
  --gray-300: #cbd5e1;
  --gray-100: #f1f5f9;
  --gray-50: #f8fafc;
  --font-head: 'Inter', 'Segoe UI', system-ui, sans-serif;
  --font-body: 'Inter', 'Segoe UI', system-ui, sans-serif;
  --radius: 12px;
  --radius-sm: 8px;
  --shadow: 0 4px 24px rgba(0,0,0,0.08);
  --shadow-lg: 0 12px 48px rgba(0,0,0,0.12);
  --transition: 0.25s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  color: var(--gray-700);
  background: var(--white);
  line-height: 1.6;
  font-size: 16px;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }
ul { list-style: none; }

.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ===== TYPOGRAPHY ===== */
h1, h2, h3, h4, h5 { font-family: var(--font-head); font-weight: 700; color: var(--dark); line-height: 1.2; }
h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.6rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.2rem, 2.5vw, 1.5rem); }
p { color: var(--gray-500); line-height: 1.75; }

.section-label {
  display: inline-block;
  background: var(--primary-light);
  color: var(--primary);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 6px 14px;
  border-radius: 100px;
  margin-bottom: 16px;
}

.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 56px;
}

.section-header p { font-size: 1.1rem; margin-top: 12px; }

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 28px;
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-weight: 600;
  transition: all var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent);
  color: var(--white);
}
.btn-primary:hover { background: var(--accent-dark); transform: translateY(-2px); box-shadow: 0 8px 24px rgba(222,80,82,0.35); }

.btn-outline {
  border: 2px solid var(--white);
  color: var(--white);
  background: transparent;
}
.btn-outline:hover { background: var(--white); color: var(--primary); }

.btn-outline-dark {
  border: 2px solid var(--primary);
  color: var(--primary);
  background: transparent;
}
.btn-outline-dark:hover { background: var(--primary); color: var(--white); }

.btn-lg { padding: 18px 36px; font-size: 1.1rem; }

/* ===== HEADER / NAV ===== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-100);
}

.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  gap: 32px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--dark);
  flex-shrink: 0;
}

.nav-logo-icon {
  width: 36px;
  height: 36px;
  background: var(--primary);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 1rem;
  font-weight: 900;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-links a {
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.95rem;
  font-weight: 500;
  color: var(--gray-700);
  transition: all var(--transition);
}
.nav-links a:hover, .nav-links a.active { color: var(--primary); background: var(--primary-light); }

.nav-cta { display: flex; align-items: center; gap: 12px; flex-shrink: 0; }

.nav-cta .btn-primary { padding: 10px 20px; font-size: 0.9rem; }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
  border-radius: var(--radius-sm);
}
.hamburger span { display: block; width: 22px; height: 2px; background: var(--dark); border-radius: 2px; transition: all var(--transition); }
.hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger.open span:nth-child(2) { opacity: 0; }
.hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

.mobile-nav {
  display: none;
  position: fixed;
  inset: 72px 0 0 0;
  background: var(--white);
  padding: 24px;
  z-index: 999;
  flex-direction: column;
  gap: 8px;
  border-top: 1px solid var(--gray-100);
  overflow-y: auto;
  transform: translateX(100%);
  transition: transform 0.3s ease;
}
.mobile-nav.open { transform: translateX(0); }

.mobile-nav a {
  display: block;
  padding: 14px 16px;
  font-size: 1.05rem;
  font-weight: 500;
  color: var(--gray-700);
  border-radius: var(--radius-sm);
  transition: all var(--transition);
}
.mobile-nav a:hover { background: var(--primary-light); color: var(--primary); }
.mobile-nav .btn-primary { text-align: center; margin-top: 16px; }

/* ===== HERO ===== */
.hero {
  background: linear-gradient(135deg, var(--dark) 0%, var(--gray-900) 60%, #1a2744 100%);
  color: var(--white);
  padding: 100px 0 80px;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 70% 50%, rgba(0,81,195,0.25) 0%, transparent 60%);
  pointer-events: none;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(0,81,195,0.25);
  border: 1px solid rgba(0,81,195,0.5);
  color: #93c5fd;
  font-size: 0.82rem;
  font-weight: 600;
  padding: 6px 14px;
  border-radius: 100px;
  margin-bottom: 24px;
}

.hero h1 { color: var(--white); margin-bottom: 20px; }
.hero h1 span { color: var(--accent); }
.hero p { color: rgba(255,255,255,0.75); font-size: 1.15rem; margin-bottom: 36px; max-width: 480px; }

.hero-actions { display: flex; flex-wrap: wrap; gap: 16px; align-items: center; }
.hero-trust { margin-top: 48px; display: flex; align-items: center; gap: 16px; }
.hero-trust-avatars { display: flex; }
.hero-trust-avatars span {
  width: 36px; height: 36px; border-radius: 50%;
  border: 2px solid var(--white);
  background: var(--primary);
  color: white;
  font-size: 0.7rem;
  font-weight: 700;
  display: flex; align-items: center; justify-content: center;
  margin-left: -10px;
}
.hero-trust-avatars span:first-child { margin-left: 0; }
.hero-trust p { color: rgba(255,255,255,0.7); font-size: 0.88rem; margin: 0; }
.hero-trust strong { color: var(--white); }

.hero-visual {
  display: flex;
  justify-content: center;
  align-items: center;
}

.dashboard-mockup {
  background: var(--white);
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 32px 80px rgba(0,0,0,0.4);
  width: 100%;
  max-width: 480px;
}

.mock-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--gray-100);
}

.mock-header h4 { font-size: 0.95rem; color: var(--dark); }
.mock-badge {
  background: #dcfce7;
  color: #166534;
  font-size: 0.72rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 100px;
}

.mock-schedule { display: flex; flex-direction: column; gap: 10px; }

.mock-shift {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  background: var(--gray-50);
  border-radius: var(--radius-sm);
}

.mock-avatar {
  width: 32px; height: 32px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 0.75rem; font-weight: 700; color: white; flex-shrink: 0;
}

.mock-shift-info { flex: 1; }
.mock-shift-info strong { font-size: 0.85rem; color: var(--dark); display: block; }
.mock-shift-info span { font-size: 0.75rem; color: var(--gray-500); }

.mock-time {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--primary);
  background: var(--primary-light);
  padding: 4px 10px;
  border-radius: 6px;
}

.mock-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-top: 20px; }
.mock-stat { text-align: center; padding: 12px; background: var(--gray-50); border-radius: var(--radius-sm); }
.mock-stat strong { display: block; font-size: 1.1rem; color: var(--dark); }
.mock-stat span { font-size: 0.72rem; color: var(--gray-500); }

/* ===== PAGE HERO (inner pages) ===== */
.page-hero {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  color: var(--white);
  padding: 80px 0;
  text-align: center;
}
.page-hero h1 { color: var(--white); margin-bottom: 16px; }
.page-hero p { color: rgba(255,255,255,0.8); font-size: 1.15rem; max-width: 560px; margin: 0 auto; }

/* ===== SECTIONS ===== */
section { padding: 96px 0; }

/* ===== FEATURES GRID ===== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 32px;
}

.feature-card {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius);
  padding: 36px;
  transition: all var(--transition);
}
.feature-card:hover { border-color: var(--primary); box-shadow: var(--shadow); transform: translateY(-4px); }

.feature-icon {
  width: 56px; height: 56px;
  border-radius: var(--radius-sm);
  background: var(--primary-light);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;
}

.feature-card h3 { margin-bottom: 10px; font-size: 1.15rem; }
.feature-card p { font-size: 0.95rem; }

/* ===== HOW IT WORKS ===== */
.how-it-works { background: var(--gray-50); }

.steps-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 40px;
  position: relative;
}

.step {
  text-align: center;
  position: relative;
}

.step-number {
  width: 56px; height: 56px;
  background: var(--primary);
  color: var(--white);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.3rem;
  font-weight: 800;
  margin: 0 auto 20px;
}

.step h3 { margin-bottom: 10px; }
.step p { font-size: 0.95rem; }

/* ===== TESTIMONIALS ===== */
.testimonials { background: var(--white); }

.testimonial-carousel {
  position: relative;
  max-width: 720px;
  margin: 0 auto;
}

.testimonial-track { overflow: hidden; border-radius: var(--radius); }

.testimonial-slide {
  display: none;
  background: var(--gray-50);
  border-radius: var(--radius);
  padding: 48px;
  border-left: 4px solid var(--primary);
}
.testimonial-slide.active { display: block; }

.quote-icon { font-size: 3rem; color: var(--primary); opacity: 0.3; line-height: 1; margin-bottom: 16px; }

.testimonial-slide blockquote {
  font-size: 1.15rem;
  color: var(--gray-700);
  font-style: italic;
  line-height: 1.7;
  margin-bottom: 24px;
}

.testimonial-author { display: flex; align-items: center; gap: 16px; }
.testimonial-avatar {
  width: 48px; height: 48px; border-radius: 50%;
  background: var(--primary);
  color: white;
  display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: 1rem;
  flex-shrink: 0;
}
.testimonial-info strong { color: var(--dark); display: block; }
.testimonial-info span { font-size: 0.875rem; color: var(--gray-500); }

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
}

.carousel-btn {
  width: 44px; height: 44px;
  border: 2px solid var(--gray-300);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  color: var(--gray-700);
  transition: all var(--transition);
  font-size: 1.1rem;
}
.carousel-btn:hover { border-color: var(--primary); color: var(--primary); background: var(--primary-light); }

.carousel-dots { display: flex; gap: 8px; }
.carousel-dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--gray-300);
  transition: all var(--transition);
}
.carousel-dot.active { background: var(--primary); width: 24px; border-radius: 4px; }

/* ===== STATS ===== */
.stats-section { background: var(--primary); padding: 72px 0; }

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 48px;
  text-align: center;
}

.stat-item strong {
  display: block;
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--white);
  margin-bottom: 8px;
}

.stat-item p { color: rgba(255,255,255,0.75); font-size: 0.95rem; margin: 0; }

/* ===== PRICING TEASER ===== */
.pricing-teaser { background: var(--gray-50); }

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
  align-items: start;
}

.pricing-card {
  background: var(--white);
  border: 2px solid var(--gray-100);
  border-radius: var(--radius);
  padding: 36px;
  position: relative;
  transition: all var(--transition);
}

.pricing-card.featured {
  border-color: var(--primary);
  box-shadow: var(--shadow-lg);
  transform: scale(1.03);
}

.pricing-badge {
  position: absolute;
  top: -14px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--accent);
  color: white;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 5px 16px;
  border-radius: 100px;
  white-space: nowrap;
}

.pricing-tier { font-size: 0.85rem; font-weight: 700; color: var(--gray-500); text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 8px; }
.pricing-price { margin-bottom: 24px; }
.pricing-price strong { font-size: 2.8rem; font-weight: 800; color: var(--dark); }
.pricing-price sub { font-size: 1rem; color: var(--gray-500); font-weight: 400; }
.pricing-price .free-label { font-size: 2rem; font-weight: 800; color: var(--dark); }

.pricing-features { margin-bottom: 28px; }
.pricing-features li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 0;
  border-bottom: 1px solid var(--gray-100);
  font-size: 0.9rem;
  color: var(--gray-700);
}
.pricing-features li:last-child { border-bottom: none; }

.check { color: #16a34a; font-weight: 700; }
.dash { color: var(--gray-300); font-weight: 700; }

.pricing-card .btn { width: 100%; justify-content: center; }
.pricing-card .btn-primary { background: var(--primary); }
.pricing-card .btn-primary:hover { background: var(--primary-dark); box-shadow: 0 8px 24px rgba(0,81,195,0.3); }

/* ===== FULL PRICING TABLE ===== */
.billing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-bottom: 48px;
}

.billing-toggle span { font-weight: 600; color: var(--gray-700); font-size: 0.95rem; }
.billing-toggle span.active-label { color: var(--dark); }

.toggle-switch {
  position: relative;
  width: 52px;
  height: 28px;
  background: var(--gray-300);
  border-radius: 100px;
  cursor: pointer;
  transition: background var(--transition);
}
.toggle-switch.on { background: var(--primary); }
.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  background: var(--white);
  border-radius: 50%;
  transition: transform var(--transition);
  box-shadow: 0 2px 6px rgba(0,0,0,0.2);
}
.toggle-switch.on::after { transform: translateX(24px); }

.savings-badge {
  background: #dcfce7;
  color: #166534;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 100px;
}

.comparison-table-wrap { overflow-x: auto; }

.comparison-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  border: 1px solid var(--gray-100);
  border-radius: var(--radius);
  overflow: hidden;
}

.comparison-table th, .comparison-table td {
  padding: 16px 20px;
  text-align: center;
  border-bottom: 1px solid var(--gray-100);
}

.comparison-table th:first-child,
.comparison-table td:first-child { text-align: left; }

.comparison-table thead th {
  background: var(--gray-900);
  color: var(--white);
  font-size: 0.9rem;
  font-weight: 700;
}

.comparison-table thead th:first-child { background: var(--gray-900); }

.comparison-table .plan-head {
  font-size: 1.1rem;
  font-weight: 800;
}

.comparison-table .plan-price {
  font-size: 0.85rem;
  color: rgba(255,255,255,0.65);
  display: block;
  margin-top: 4px;
  font-weight: 400;
}

.comparison-table .plan-price.featured-price { color: #93c5fd; }

.comparison-table thead th.featured-col {
  background: var(--primary);
}

.comparison-table tbody tr:last-child td { border-bottom: none; }
.comparison-table tbody tr:nth-child(even) td { background: var(--gray-50); }

.comparison-table td .check { font-size: 1.1rem; }
.comparison-table td .dash { font-size: 1.1rem; }

.comparison-table .feature-name { font-weight: 500; color: var(--dark); font-size: 0.9rem; }
.comparison-table .feature-name small { display: block; color: var(--gray-500); font-weight: 400; font-size: 0.8rem; }

/* ===== FAQ ===== */
.faq-section { background: var(--gray-50); }

.faq-list { max-width: 720px; margin: 0 auto; }

.faq-item {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-sm);
  margin-bottom: 12px;
  overflow: hidden;
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--dark);
  text-align: left;
  transition: all var(--transition);
  background: none;
}
.faq-question:hover { background: var(--gray-50); }
.faq-question.open { color: var(--primary); }

.faq-icon { font-size: 1.3rem; color: var(--primary); transition: transform var(--transition); flex-shrink: 0; }
.faq-question.open .faq-icon { transform: rotate(45deg); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.3s ease;
  padding: 0 24px;
}
.faq-answer.open { max-height: 300px; padding: 0 24px 20px; }
.faq-answer p { font-size: 0.95rem; color: var(--gray-500); }

/* ===== CTA BLOCK ===== */
.cta-section {
  background: linear-gradient(135deg, var(--dark) 0%, var(--gray-900) 100%);
  padding: 100px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-section::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, rgba(0,81,195,0.3) 0%, transparent 70%);
  pointer-events: none;
}

.cta-section h2 { color: var(--white); position: relative; margin-bottom: 16px; }
.cta-section p { color: rgba(255,255,255,0.7); font-size: 1.1rem; position: relative; margin-bottom: 36px; max-width: 480px; margin-left: auto; margin-right: auto; }

.cta-actions { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; position: relative; }

/* ===== FEATURES PAGE ===== */
.feature-detail {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}

.feature-detail.reverse { direction: rtl; }
.feature-detail.reverse > * { direction: ltr; }

.feature-detail-text .section-label { margin-bottom: 16px; }
.feature-detail-text h2 { margin-bottom: 16px; }
.feature-detail-text p { margin-bottom: 24px; }

.feature-bullets { display: flex; flex-direction: column; gap: 12px; }
.feature-bullet {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  font-size: 0.95rem;
  color: var(--gray-700);
}
.feature-bullet-icon { width: 22px; height: 22px; background: #dcfce7; color: #16a34a; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 0.7rem; flex-shrink: 0; margin-top: 2px; font-weight: 800; }

.feature-detail-visual {
  background: var(--gray-50);
  border-radius: var(--radius);
  padding: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 340px;
}

.feature-illustration {
  width: 100%;
  max-width: 340px;
  background: var(--white);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
}

/* ===== INTEGRATIONS ===== */
.integrations-section { background: var(--gray-50); }

.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 28px;
}

.integration-category {
  background: var(--white);
  border-radius: var(--radius);
  padding: 28px;
  border: 1px solid var(--gray-100);
}

.integration-category h3 { font-size: 1rem; margin-bottom: 16px; color: var(--dark); }

.integration-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.integration-chip {
  background: var(--gray-50);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-sm);
  padding: 6px 14px;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--gray-700);
}

/* ===== ABOUT PAGE ===== */
.mission-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}

.mission-text h2 { margin-bottom: 20px; }
.mission-text p { margin-bottom: 16px; }

.mission-visual {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  border-radius: var(--radius);
  padding: 48px;
  color: white;
  text-align: center;
}

.mission-visual .year { font-size: 4rem; font-weight: 800; display: block; }
.mission-visual .year-label { font-size: 0.9rem; opacity: 0.7; margin-bottom: 24px; display: block; }
.mission-values { display: flex; flex-direction: column; gap: 12px; }
.mission-value {
  background: rgba(255,255,255,0.1);
  border-radius: var(--radius-sm);
  padding: 12px 16px;
  font-weight: 600;
  font-size: 0.9rem;
}

.team-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 28px;
}

.team-card {
  text-align: center;
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius);
  padding: 36px 24px;
  transition: all var(--transition);
}
.team-card:hover { box-shadow: var(--shadow); transform: translateY(-4px); }

.team-avatar {
  width: 80px; height: 80px;
  border-radius: 50%;
  margin: 0 auto 16px;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.8rem;
  font-weight: 800;
  color: var(--white);
}

.team-card h3 { font-size: 1.1rem; margin-bottom: 4px; }
.team-card .role { font-size: 0.85rem; color: var(--primary); font-weight: 600; }

/* ===== CONTACT ===== */
.contact-grid {
  display: grid;
  grid-template-columns: 3fr 2fr;
  gap: 64px;
  align-items: start;
}

.contact-form-card {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius);
  padding: 48px;
  box-shadow: var(--shadow);
}

.form-group { margin-bottom: 20px; }

.form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }

label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--dark);
  margin-bottom: 8px;
}

input, select, textarea {
  width: 100%;
  padding: 12px 16px;
  border: 1.5px solid var(--gray-300);
  border-radius: var(--radius-sm);
  font-size: 0.95rem;
  font-family: inherit;
  color: var(--dark);
  transition: all var(--transition);
  background: var(--white);
  outline: none;
}

input:focus, select:focus, textarea:focus { border-color: var(--primary); box-shadow: 0 0 0 3px var(--primary-light); }

input.error, select.error, textarea.error { border-color: var(--accent); }
.error-msg { font-size: 0.8rem; color: var(--accent); margin-top: 4px; display: none; }
.error-msg.show { display: block; }

textarea { resize: vertical; min-height: 120px; }

.form-submit .btn { width: 100%; justify-content: center; }

.success-message {
  display: none;
  text-align: center;
  padding: 48px 24px;
}
.success-message.show { display: block; }
.success-icon { font-size: 3rem; margin-bottom: 16px; }
.success-message h3 { margin-bottom: 12px; }
.success-message p { font-size: 0.95rem; }

.contact-sidebar { display: flex; flex-direction: column; gap: 28px; }

.contact-info-card {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius);
  padding: 28px;
}
.contact-info-card h3 { font-size: 1rem; margin-bottom: 16px; }

.contact-item { display: flex; align-items: flex-start; gap: 12px; margin-bottom: 16px; }
.contact-item:last-child { margin-bottom: 0; }
.contact-item-icon { width: 36px; height: 36px; background: var(--primary-light); border-radius: var(--radius-sm); display: flex; align-items: center; justify-content: center; font-size: 1rem; flex-shrink: 0; }
.contact-item-text strong { display: block; font-size: 0.85rem; color: var(--dark); font-weight: 600; }
.contact-item-text span { font-size: 0.85rem; color: var(--gray-500); }

.locations-card {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius);
  padding: 28px;
}
.locations-card h3 { font-size: 1rem; margin-bottom: 16px; }
.location-item { padding: 12px 0; border-bottom: 1px solid var(--gray-100); font-size: 0.9rem; color: var(--gray-700); }
.location-item:last-child { border-bottom: none; }
.location-item strong { color: var(--dark); display: block; margin-bottom: 2px; }

/* ===== FOOTER ===== */
.site-footer {
  background: var(--dark);
  color: rgba(255,255,255,0.6);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}

.footer-brand { }
.footer-brand .nav-logo { color: white; margin-bottom: 16px; }
.footer-brand p { font-size: 0.88rem; line-height: 1.7; max-width: 240px; }

.footer-col h4 { color: var(--white); font-size: 0.85rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 16px; }
.footer-col ul { display: flex; flex-direction: column; gap: 10px; }
.footer-col ul a { font-size: 0.88rem; transition: color var(--transition); }
.footer-col ul a:hover { color: var(--white); }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.08);
  padding-top: 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  font-size: 0.85rem;
}

/* ===== UTILITY ===== */
.alt-bg { background: var(--gray-50); }
.text-center { text-align: center; }
.mt-8 { margin-top: 32px; }

/* ===== ANIMATIONS ===== */
.count-up { display: inline-block; }

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

.fade-up { animation: fadeUp 0.6s ease forwards; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .stats-grid { grid-template-columns: repeat(2, 1fr); gap: 32px; }
}

@media (max-width: 768px) {
  section { padding: 64px 0; }

  .nav-links, .nav-cta { display: none; }
  .hamburger { display: flex; }
  .mobile-nav { display: flex; }

  .hero { padding: 64px 0; }
  .hero-grid { grid-template-columns: 1fr; gap: 48px; }
  .hero-visual { display: none; }

  .page-hero { padding: 56px 0; }

  .features-grid { grid-template-columns: 1fr; }
  .steps-grid { grid-template-columns: 1fr 1fr; }

  .pricing-cards { grid-template-columns: 1fr; }
  .pricing-card.featured { transform: scale(1); }

  .feature-detail { grid-template-columns: 1fr; gap: 40px; }
  .feature-detail.reverse { direction: ltr; }
  .feature-detail-visual { display: none; }

  .mission-grid { grid-template-columns: 1fr; gap: 40px; }
  .mission-visual { display: none; }

  .team-grid { grid-template-columns: repeat(2, 1fr); }

  .contact-grid { grid-template-columns: 1fr; }
  .form-row { grid-template-columns: 1fr; }
  .contact-form-card { padding: 32px 24px; }

  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .footer-brand { grid-column: 1 / -1; }

  .stats-grid { grid-template-columns: repeat(2, 1fr); }

  .testimonial-slide { padding: 32px 24px; }

  .cta-section { padding: 72px 0; }

  .hero-trust { flex-wrap: wrap; }
}

@media (max-width: 480px) {
  .steps-grid { grid-template-columns: 1fr; }
  .team-grid { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .hero-actions { flex-direction: column; }
  .hero-actions .btn { width: 100%; justify-content: center; }
}

/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --primary: #0051C3;
  --primary-dark: #003d94;
  --primary-light: #e8f0fe;
  --accent: #DE5052;
  --accent-dark: #b83a3c;
  --white: #FFFFFF;
  --dark: #0f172a;
  --gray-900: #1e293b;
  --gray-700: #334155;
  --gray-500: #64748b;
  --gray-300: #cbd5e1;
  --gray-100: #f1f5f9;
  --gray-50: #f8fafc;
  --font-head: 'Inter', 'Segoe UI', system-ui, sans-serif;
  --font-body: 'Inter', 'Segoe UI', system-ui, sans-serif;
  --radius: 12px;
  --radius-sm: 8px;
  --shadow: 0 4px 24px rgba(0,0,0,0.08);
  --shadow-lg: 0 12px 48px rgba(0,0,0,0.12);
  --transition: 0.25s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  color: var(--gray-700);
  background: var(--white);
  line-height: 1.6;
  font-size: 16px;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }
ul { list-style: none; }

.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ===== TYPOGRAPHY ===== */
h1, h2, h3, h4, h5 { font-family: var(--font-head); font-weight: 700; color: var(--dark); line-height: 1.2; }
h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.6rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.2rem, 2.5vw, 1.5rem); }
p { color: var(--gray-500); line-height: 1.75; }

.section-label {
  display: inline-block;
  background: var(--primary-light);
  color: var(--primary);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 6px 14px;
  border-radius: 100px;
  margin-bottom: 16px;
}

.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 56px;
}

.section-header p { font-size: 1.1rem; margin-top: 12px; }

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 28px;
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-weight: 600;
  transition: all var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent);
  color: var(--white);
}
.btn-primary:hover { background: var(--accent-dark); transform: translateY(-2px); box-shadow: 0 8px 24px rgba(222,80,82,0.35); }

.btn-outline {
  border: 2px solid var(--white);
  color: var(--white);
  background: transparent;
}
.btn-outline:hover { background: var(--white); color: var(--primary); }

.btn-outline-dark {
  border: 2px solid var(--primary);
  color: var(--primary);
  background: transparent;
}
.btn-outline-dark:hover { background: var(--primary); color: var(--white); }

.btn-lg { padding: 18px 36px; font-size: 1.1rem; }

/* ===== HEADER / NAV ===== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-100);
}

.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  gap: 32px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--dark);
  flex-shrink: 0;
}

.nav-logo-icon {
  width: 36px;
  height: 36px;
  background: var(--primary);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 1rem;
  font-weight: 900;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-links a {
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.95rem;
  font-weight: 500;
  color: var(--gray-700);
  transition: all var(--transition);
}
.nav-links a:hover, .nav-links a.active { color: var(--primary); background: var(--primary-light); }

.nav-cta { display: flex; align-items: center; gap: 12px; flex-shrink: 0; }

.nav-cta .btn-primary { padding: 10px 20px; font-size: 0.9rem; }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
  border-radius: var(--radius-sm);
}
.hamburger span { display: block; width: 22px; height: 2px; background: var(--dark); border-radius: 2px; transition: all var(--transition); }
.hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger.open span:nth-child(2) { opacity: 0; }
.hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

.mobile-nav {
  display: none;
  position: fixed;
  inset: 72px 0 0 0;
  background: var(--white);
  padding: 24px;
  z-index: 999;
  flex-direction: column;
  gap: 8px;
  border-top: 1px solid var(--gray-100);
  overflow-y: auto;
  transform: translateX(100%);
  transition: transform 0.3s ease;
}
.mobile-nav.open { transform: translateX(0); }

.mobile-nav a {
  display: block;
  padding: 14px 16px;
  font-size: 1.05rem;
  font-weight: 500;
  color: var(--gray-700);
  border-radius: var(--radius-sm);
  transition: all var(--transition);
}
.mobile-nav a:hover { background: var(--primary-light); color: var(--primary); }
.mobile-nav .btn-primary { text-align: center; margin-top: 16px; }

/* ===== HERO ===== */
.hero {
  background: linear-gradient(135deg, var(--dark) 0%, var(--gray-900) 60%, #1a2744 100%);
  color: var(--white);
  padding: 100px 0 80px;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 70% 50%, rgba(0,81,195,0.25) 0%, transparent 60%);
  pointer-events: none;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(0,81,195,0.25);
  border: 1px solid rgba(0,81,195,0.5);
  color: #93c5fd;
  font-size: 0.82rem;
  font-weight: 600;
  padding: 6px 14px;
  border-radius: 100px;
  margin-bottom: 24px;
}

.hero h1 { color: var(--white); margin-bottom: 20px; }
.hero h1 span { color: var(--accent); }
.hero p { color: rgba(255,255,255,0.75); font-size: 1.15rem; margin-bottom: 36px; max-width: 480px; }

.hero-actions { display: flex; flex-wrap: wrap; gap: 16px; align-items: center; }
.hero-trust { margin-top: 48px; display: flex; align-items: center; gap: 16px; }
.hero-trust-avatars { display: flex; }
.hero-trust-avatars span {
  width: 36px; height: 36px; border-radius: 50%;
  border: 2px solid var(--white);
  background: var(--primary);
  color: white;
  font-size: 0.7rem;
  font-weight: 700;
  display: flex; align-items: center; justify-content: center;
  margin-left: -10px;
}
.hero-trust-avatars span:first-child { margin-left: 0; }
.hero-trust p { color: rgba(255,255,255,0.7); font-size: 0.88rem; margin: 0; }
.hero-trust strong { color: var(--white); }

.hero-visual {
  display: flex;
  justify-content: center;
  align-items: center;
}

.dashboard-mockup {
  background: var(--white);
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 32px 80px rgba(0,0,0,0.4);
  width: 100%;
  max-width: 480px;
}

.mock-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--gray-100);
}

.mock-header h4 { font-size: 0.95rem; color: var(--dark); }
.mock-badge {
  background: #dcfce7;
  color: #166534;
  font-size: 0.72rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 100px;
}

.mock-schedule { display: flex; flex-direction: column; gap: 10px; }

.mock-shift {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  background: var(--gray-50);
  border-radius: var(--radius-sm);
}

.mock-avatar {
  width: 32px; height: 32px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 0.75rem; font-weight: 700; color: white; flex-shrink: 0;
}

.mock-shift-info { flex: 1; }
.mock-shift-info strong { font-size: 0.85rem; color: var(--dark); display: block; }
.mock-shift-info span { font-size: 0.75rem; color: var(--gray-500); }

.mock-time {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--primary);
  background: var(--primary-light);
  padding: 4px 10px;
  border-radius: 6px;
}

.mock-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-top: 20px; }
.mock-stat { text-align: center; padding: 12px; background: var(--gray-50); border-radius: var(--radius-sm); }
.mock-stat strong { display: block; font-size: 1.1rem; color: var(--dark); }
.mock-stat span { font-size: 0.72rem; color: var(--gray-500); }

/* ===== PAGE HERO (inner pages) ===== */
.page-hero {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  color: var(--white);
  padding: 80px 0;
  text-align: center;
}
.page-hero h1 { color: var(--white); margin-bottom: 16px; }
.page-hero p { color: rgba(255,255,255,0.8); font-size: 1.15rem; max-width: 560px; margin: 0 auto; }

/* ===== SECTIONS ===== */
section { padding: 96px 0; }

/* ===== FEATURES GRID ===== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 32px;
}

.feature-card {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius);
  padding: 36px;
  transition: all var(--transition);
}
.feature-card:hover { border-color: var(--primary); box-shadow: var(--shadow); transform: translateY(-4px); }

.feature-icon {
  width: 56px; height: 56px;
  border-radius: var(--radius-sm);
  background: var(--primary-light);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;
}

.feature-card h3 { margin-bottom: 10px; font-size: 1.15rem; }
.feature-card p { font-size: 0.95rem; }

/* ===== HOW IT WORKS ===== */
.how-it-works { background: var(--gray-50); }

.steps-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 40px;
  position: relative;
}

.step {
  text-align: center;
  position: relative;
}

.step-number {
  width: 56px; height: 56px;
  background: var(--primary);
  color: var(--white);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.3rem;
  font-weight: 800;
  margin: 0 auto 20px;
}

.step h3 { margin-bottom: 10px; }
.step p { font-size: 0.95rem; }

/* ===== TESTIMONIALS ===== */
.testimonials { background: var(--white); }

.testimonial-carousel {
  position: relative;
  max-width: 720px;
  margin: 0 auto;
}

.testimonial-track { overflow: hidden; border-radius: var(--radius); }

.testimonial-slide {
  display: none;
  background: var(--gray-50);
  border-radius: var(--radius);
  padding: 48px;
  border-left: 4px solid var(--primary);
}
.testimonial-slide.active { display: block; }

.quote-icon { font-size: 3rem; color: var(--primary); opacity: 0.3; line-height: 1; margin-bottom: 16px; }

.testimonial-slide blockquote {
  font-size: 1.15rem;
  color: var(--gray-700);
  font-style: italic;
  line-height: 1.7;
  margin-bottom: 24px;
}

.testimonial-author { display: flex; align-items: center; gap: 16px; }
.testimonial-avatar {
  width: 48px; height: 48px; border-radius: 50%;
  background: var(--primary);
  color: white;
  display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: 1rem;
  flex-shrink: 0;
}
.testimonial-info strong { color: var(--dark); display: block; }
.testimonial-info span { font-size: 0.875rem; color: var(--gray-500); }

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
}

.carousel-btn {
  width: 44px; height: 44px;
  border: 2px solid var(--gray-300);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  color: var(--gray-700);
  transition: all var(--transition);
  font-size: 1.1rem;
}
.carousel-btn:hover { border-color: var(--primary); color: var(--primary); background: var(--primary-light); }

.carousel-dots { display: flex; gap: 8px; }
.carousel-dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--gray-300);
  transition: all var(--transition);
}
.carousel-dot.active { background: var(--primary); width: 24px; border-radius: 4px; }

/* ===== STATS ===== */
.stats-section { background: var(--primary); padding: 72px 0; }

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 48px;
  text-align: center;
}

.stat-item strong {
  display: block;
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--white);
  margin-bottom: 8px;
}

.stat-item p { color: rgba(255,255,255,0.75); font-size: 0.95rem; margin: 0; }

/* ===== PRICING TEASER ===== */
.pricing-teaser { background: var(--gray-50); }

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
  align-items: start;
}

.pricing-card {
  background: var(--white);
  border: 2px solid var(--gray-100);
  border-radius: var(--radius);
  padding: 36px;
  position: relative;
  transition: all var(--transition);
}

.pricing-card.featured {
  border-color: var(--primary);
  box-shadow: var(--shadow-lg);
  transform: scale(1.03);
}

.pricing-badge {
  position: absolute;
  top: -14px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--accent);
  color: white;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 5px 16px;
  border-radius: 100px;
  white-space: nowrap;
}

.pricing-tier { font-size: 0.85rem; font-weight: 700; color: var(--gray-500); text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 8px; }
.pricing-price { margin-bottom: 24px; }
.pricing-price strong { font-size: 2.8rem; font-weight: 800; color: var(--dark); }
.pricing-price sub { font-size: 1rem; color: var(--gray-500); font-weight: 400; }
.pricing-price .free-label { font-size: 2rem; font-weight: 800; color: var(--dark); }

.pricing-features { margin-bottom: 28px; }
.pricing-features li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 0;
  border-bottom: 1px solid var(--gray-100);
  font-size: 0.9rem;
  color: var(--gray-700);
}
.pricing-features li:last-child { border-bottom: none; }

.check { color: #16a34a; font-weight: 700; }
.dash { color: var(--gray-300); font-weight: 700; }

.pricing-card .btn { width: 100%; justify-content: center; }
.pricing-card .btn-primary { background: var(--primary); }
.pricing-card .btn-primary:hover { background: var(--primary-dark); box-shadow: 0 8px 24px rgba(0,81,195,0.3); }

/* ===== FULL PRICING TABLE ===== */
.billing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-bottom: 48px;
}

.billing-toggle span { font-weight: 600; color: var(--gray-700); font-size: 0.95rem; }
.billing-toggle span.active-label { color: var(--dark); }

.toggle-switch {
  position: relative;
  width: 52px;
  height: 28px;
  background: var(--gray-300);
  border-radius: 100px;
  cursor: pointer;
  transition: background var(--transition);
}
.toggle-switch.on { background: var(--primary); }
.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  background: var(--white);
  border-radius: 50%;
  transition: transform var(--transition);
  box-shadow: 0 2px 6px rgba(0,0,0,0.2);
}
.toggle-switch.on::after { transform: translateX(24px); }

.savings-badge {
  background: #dcfce7;
  color: #166534;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 100px;
}

.comparison-table-wrap { overflow-x: auto; }

.comparison-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  border: 1px solid var(--gray-100);
  border-radius: var(--radius);
  overflow: hidden;
}

.comparison-table th, .comparison-table td {
  padding: 16px 20px;
  text-align: center;
  border-bottom: 1px solid var(--gray-100);
}

.comparison-table th:first-child,
.comparison-table td:first-child { text-align: left; }

.comparison-table thead th {
  background: var(--gray-900);
  color: var(--white);
  font-size: 0.9rem;
  font-weight: 700;
}

.comparison-table thead th:first-child { background: var(--gray-900); }

.comparison-table .plan-head {
  font-size: 1.1rem;
  font-weight: 800;
}

.comparison-table .plan-price {
  font-size: 0.85rem;
  color: rgba(255,255,255,0.65);
  display: block;
  margin-top: 4px;
  font-weight: 400;
}

.comparison-table .plan-price.featured-price { color: #93c5fd; }

.comparison-table thead th.featured-col {
  background: var(--primary);
}

.comparison-table tbody tr:last-child td { border-bottom: none; }
.comparison-table tbody tr:nth-child(even) td { background: var(--gray-50); }

.comparison-table td .check { font-size: 1.1rem; }
.comparison-table td .dash { font-size: 1.1rem; }

.comparison-table .feature-name { font-weight: 500; color: var(--dark); font-size: 0.9rem; }
.comparison-table .feature-name small { display: block; color: var(--gray-500); font-weight: 400; font-size: 0.8rem; }

/* ===== FAQ ===== */
.faq-section { background: var(--gray-50); }

.faq-list { max-width: 720px; margin: 0 auto; }

.faq-item {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-sm);
  margin-bottom: 12px;
  overflow: hidden;
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--dark);
  text-align: left;
  transition: all var(--transition);
  background: none;
}
.faq-question:hover { background: var(--gray-50); }
.faq-question.open { color: var(--primary); }

.faq-icon { font-size: 1.3rem; color: var(--primary); transition: transform var(--transition); flex-shrink: 0; }
.faq-question.open .faq-icon { transform: rotate(45deg); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.3s ease;
  padding: 0 24px;
}
.faq-answer.open { max-height: 300px; padding: 0 24px 20px; }
.faq-answer p { font-size: 0.95rem; color: var(--gray-500); }

/* ===== CTA BLOCK ===== */
.cta-section {
  background: linear-gradient(135deg, var(--dark) 0%, var(--gray-900) 100%);
  padding: 100px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-section::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, rgba(0,81,195,0.3) 0%, transparent 70%);
  pointer-events: none;
}

.cta-section h2 { color: var(--white); position: relative; margin-bottom: 16px; }
.cta-section p { color: rgba(255,255,255,0.7); font-size: 1.1rem; position: relative; margin-bottom: 36px; max-width: 480px; margin-left: auto; margin-right: auto; }

.cta-actions { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; position: relative; }

/* ===== FEATURES PAGE ===== */
.feature-detail {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}

.feature-detail.reverse { direction: rtl; }
.feature-detail.reverse > * { direction: ltr; }

.feature-detail-text .section-label { margin-bottom: 16px; }
.feature-detail-text h2 { margin-bottom: 16px; }
.feature-detail-text p { margin-bottom: 24px; }

.feature-bullets { display: flex; flex-direction: column; gap: 12px; }
.feature-bullet {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  font-size: 0.95rem;
  color: var(--gray-700);
}
.feature-bullet-icon { width: 22px; height: 22px; background: #dcfce7; color: #16a34a; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 0.7rem; flex-shrink: 0; margin-top: 2px; font-weight: 800; }

.feature-detail-visual {
  background: var(--gray-50);
  border-radius: var(--radius);
  padding: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 340px;
}

.feature-illustration {
  width: 100%;
  max-width: 340px;
  background: var(--white);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
}

/* ===== INTEGRATIONS ===== */
.integrations-section { background: var(--gray-50); }

.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 28px;
}

.integration-category {
  background: var(--white);
  border-radius: var(--radius);
  padding: 28px;
  border: 1px solid var(--gray-100);
}

.integration-category h3 { font-size: 1rem; margin-bottom: 16px; color: var(--dark); }

.integration-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.integration-chip {
  background: var(--gray-50);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-sm);
  padding: 6px 14px;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--gray-700);
}

/* ===== ABOUT PAGE ===== */
.mission-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}

.mission-text h2 { margin-bottom: 20px; }
.mission-text p { margin-bottom: 16px; }

.mission-visual {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  border-radius: var(--radius);
  padding: 48px;
  color: white;
  text-align: center;
}

.mission-visual .year { font-size: 4rem; font-weight: 800; display: block; }
.mission-visual .year-label { font-size: 0.9rem; opacity: 0.7; margin-bottom: 24px; display: block; }
.mission-values { display: flex; flex-direction: column; gap: 12px; }
.mission-value {
  background: rgba(255,255,255,0.1);
  border-radius: var(--radius-sm);
  padding: 12px 16px;
  font-weight: 600;
  font-size: 0.9rem;
}

.team-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 28px;
}

.team-card {
  text-align: center;
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius);
  padding: 36px 24px;
  transition: all var(--transition);
}
.team-card:hover { box-shadow: var(--shadow); transform: translateY(-4px); }

.team-avatar {
  width: 80px; height: 80px;
  border-radius: 50%;
  margin: 0 auto 16px;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.8rem;
  font-weight: 800;
  color: var(--white);
}

.team-card h3 { font-size: 1.1rem; margin-bottom: 4px; }
.team-card .role { font-size: 0.85rem; color: var(--primary); font-weight: 600; }

/* ===== CONTACT ===== */
.contact-grid {
  display: grid;
  grid-template-columns: 3fr 2fr;
  gap: 64px;
  align-items: start;
}

.contact-form-card {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius);
  padding: 48px;
  box-shadow: var(--shadow);
}

.form-group { margin-bottom: 20px; }

.form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }

label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--dark);
  margin-bottom: 8px;
}

input, select, textarea {
  width: 100%;
  padding: 12px 16px;
  border: 1.5px solid var(--gray-300);
  border-radius: var(--radius-sm);
  font-size: 0.95rem;
  font-family: inherit;
  color: var(--dark);
  transition: all var(--transition);
  background: var(--white);
  outline: none;
}

input:focus, select:focus, textarea:focus { border-color: var(--primary); box-shadow: 0 0 0 3px var(--primary-light); }

input.error, select.error, textarea.error { border-color: var(--accent); }
.error-msg { font-size: 0.8rem; color: var(--accent); margin-top: 4px; display: none; }
.error-msg.show { display: block; }

textarea { resize: vertical; min-height: 120px; }

.form-submit .btn { width: 100%; justify-content: center; }

.success-message {
  display: none;
  text-align: center;
  padding: 48px 24px;
}
.success-message.show { display: block; }
.success-icon { font-size: 3rem; margin-bottom: 16px; }
.success-message h3 { margin-bottom: 12px; }
.success-message p { font-size: 0.95rem; }

.contact-sidebar { display: flex; flex-direction: column; gap: 28px; }

.contact-info-card {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius);
  padding: 28px;
}
.contact-info-card h3 { font-size: 1rem; margin-bottom: 16px; }

.contact-item { display: flex; align-items: flex-start; gap: 12px; margin-bottom: 16px; }
.contact-item:last-child { margin-bottom: 0; }
.contact-item-icon { width: 36px; height: 36px; background: var(--primary-light); border-radius: var(--radius-sm); display: flex; align-items: center; justify-content: center; font-size: 1rem; flex-shrink: 0; }
.contact-item-text strong { display: block; font-size: 0.85rem; color: var(--dark); font-weight: 600; }
.contact-item-text span { font-size: 0.85rem; color: var(--gray-500); }

.locations-card {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius);
  padding: 28px;
}
.locations-card h3 { font-size: 1rem; margin-bottom: 16px; }
.location-item { padding: 12px 0; border-bottom: 1px solid var(--gray-100); font-size: 0.9rem; color: var(--gray-700); }
.location-item:last-child { border-bottom: none; }
.location-item strong { color: var(--dark); display: block; margin-bottom: 2px; }

/* ===== FOOTER ===== */
.site-footer {
  background: var(--dark);
  color: rgba(255,255,255,0.6);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}

.footer-brand { }
.footer-brand .nav-logo { color: white; margin-bottom: 16px; }
.footer-brand p { font-size: 0.88rem; line-height: 1.7; max-width: 240px; }

.footer-col h4 { color: var(--white); font-size: 0.85rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 16px; }
.footer-col ul { display: flex; flex-direction: column; gap: 10px; }
.footer-col ul a { font-size: 0.88rem; transition: color var(--transition); }
.footer-col ul a:hover { color: var(--white); }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.08);
  padding-top: 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  font-size: 0.85rem;
}

/* ===== UTILITY ===== */
.alt-bg { background: var(--gray-50); }
.text-center { text-align: center; }
.mt-8 { margin-top: 32px; }

/* ===== ANIMATIONS ===== */
.count-up { display: inline-block; }

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

.fade-up { animation: fadeUp 0.6s ease forwards; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .stats-grid { grid-template-columns: repeat(2, 1fr); gap: 32px; }
}

@media (max-width: 768px) {
  section { padding: 64px 0; }

  .nav-links, .nav-cta { display: none; }
  .hamburger { display: flex; }
  .mobile-nav { display: flex; }

  .hero { padding: 64px 0; }
  .hero-grid { grid-template-columns: 1fr; gap: 48px; }
  .hero-visual { display: none; }

  .page-hero { padding: 56px 0; }

  .features-grid { grid-template-columns: 1fr; }
  .steps-grid { grid-template-columns: 1fr 1fr; }

  .pricing-cards { grid-template-columns: 1fr; }
  .pricing-card.featured { transform: scale(1); }

  .feature-detail { grid-template-columns: 1fr; gap: 40px; }
  .feature-detail.reverse { direction: ltr; }
  .feature-detail-visual { display: none; }

  .mission-grid { grid-template-columns: 1fr; gap: 40px; }
  .mission-visual { display: none; }

  .team-grid { grid-template-columns: repeat(2, 1fr); }

  .contact-grid { grid-template-columns: 1fr; }
  .form-row { grid-template-columns: 1fr; }
  .contact-form-card { padding: 32px 24px; }

  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .footer-brand { grid-column: 1 / -1; }

  .stats-grid { grid-template-columns: repeat(2, 1fr); }

  .testimonial-slide { padding: 32px 24px; }

  .cta-section { padding: 72px 0; }

  .hero-trust { flex-wrap: wrap; }
}

@media (max-width: 480px) {
  .steps-grid { grid-template-columns: 1fr; }
  .team-grid { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .hero-actions { flex-direction: column; }
  .hero-actions .btn { width: 100%; justify-content: center; }
}

raw_arguments.content:
/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --primary: #0051C3;
  --primary-dark: #003d94;
  --primary-light: #e8f0fe;
  --accent: #DE5052;
  --accent-dark: #b83a3c;
  --white: #FFFFFF;
  --dark: #0f172a;
  --gray-900: #1e293b;
  --gray-700: #334155;
  --gray-500: #64748b;
  --gray-300: #cbd5e1;
  --gray-100: #f1f5f9;
  --gray-50: #f8fafc;
  --font-head: 'Inter', 'Segoe UI', system-ui, sans-serif;
  --font-body: 'Inter', 'Segoe UI', system-ui, sans-serif;
  --radius: 12px;
  --radius-sm: 8px;
  --shadow: 0 4px 24px rgba(0,0,0,0.08);
  --shadow-lg: 0 12px 48px rgba(0,0,0,0.12);
  --transition: 0.25s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  color: var(--gray-700);
  background: var(--white);
  line-height: 1.6;
  font-size: 16px;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }
ul { list-style: none; }

.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ===== TYPOGRAPHY ===== */
h1, h2, h3, h4, h5 { font-family: var(--font-head); font-weight: 700; color: var(--dark); line-height: 1.2; }
h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.6rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.2rem, 2.5vw, 1.5rem); }
p { color: var(--gray-500); line-height: 1.75; }

.section-label {
  display: inline-block;
  background: var(--primary-light);
  color: var(--primary);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 6px 14px;
  border-radius: 100px;
  margin-bottom: 16px;
}

.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 56px;
}

.section-header p { font-size: 1.1rem; margin-top: 12px; }

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 28px;
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-weight: 600;
  transition: all var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent);
  color: var(--white);
}
.btn-primary:hover { background: var(--accent-dark); transform: translateY(-2px); box-shadow: 0 8px 24px rgba(222,80,82,0.35); }

.btn-outline {
  border: 2px solid var(--white);
  color: var(--white);
  background: transparent;
}
.btn-outline:hover { background: var(--white); color: var(--primary); }

.btn-outline-dark {
  border: 2px solid var(--primary);
  color: var(--primary);
  background: transparent;
}
.btn-outline-dark:hover { background: var(--primary); color: var(--white); }

.btn-lg { padding: 18px 36px; font-size: 1.1rem; }

/* ===== HEADER / NAV ===== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-100);
}

.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  gap: 32px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--dark);
  flex-shrink: 0;
}

.nav-logo-icon {
  width: 36px;
  height: 36px;
  background: var(--primary);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 1rem;
  font-weight: 900;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-links a {
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.95rem;
  font-weight: 500;
  color: var(--gray-700);
  transition: all var(--transition);
}
.nav-links a:hover, .nav-links a.active { color: var(--primary); background: var(--primary-light); }

.nav-cta { display: flex; align-items: center; gap: 12px; flex-shrink: 0; }

.nav-cta .btn-primary { padding: 10px 20px; font-size: 0.9rem; }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
  border-radius: var(--radius-sm);
}
.hamburger span { display: block; width: 22px; height: 2px; background: var(--dark); border-radius: 2px; transition: all var(--transition); }
.hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger.open span:nth-child(2) { opacity: 0; }
.hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

.mobile-nav {
  display: none;
  position: fixed;
  inset: 72px 0 0 0;
  background: var(--white);
  padding: 24px;
  z-index: 999;
  flex-direction: column;
  gap: 8px;
  border-top: 1px solid var(--gray-100);
  overflow-y: auto;
  transform: translateX(100%);
  transition: transform 0.3s ease;
}
.mobile-nav.open { transform: translateX(0); }

.mobile-nav a {
  display: block;
  padding: 14px 16px;
  font-size: 1.05rem;
  font-weight: 500;
  color: var(--gray-700);
  border-radius: var(--radius-sm);
  transition: all var(--transition);
}
.mobile-nav a:hover { background: var(--primary-light); color: var(--primary); }
.mobile-nav .btn-primary { text-align: center; margin-top: 16px; }

/* ===== HERO ===== */
.hero {
  background: linear-gradient(135deg, var(--dark) 0%, var(--gray-900) 60%, #1a2744 100%);
  color: var(--white);
  padding: 100px 0 80px;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 70% 50%, rgba(0,81,195,0.25) 0%, transparent 60%);
  pointer-events: none;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(0,81,195,0.25);
  border: 1px solid rgba(0,81,195,0.5);
  color: #93c5fd;
  font-size: 0.82rem;
  font-weight: 600;
  padding: 6px 14px;
  border-radius: 100px;
  margin-bottom: 24px;
}

.hero h1 { color: var(--white); margin-bottom: 20px; }
.hero h1 span { color: var(--accent); }
.hero p { color: rgba(255,255,255,0.75); font-size: 1.15rem; margin-bottom: 36px; max-width: 480px; }

.hero-actions { display: flex; flex-wrap: wrap; gap: 16px; align-items: center; }
.hero-trust { margin-top: 48px; display: flex; align-items: center; gap: 16px; }
.hero-trust-avatars { display: flex; }
.hero-trust-avatars span {
  width: 36px; height: 36px; border-radius: 50%;
  border: 2px solid var(--white);
  background: var(--primary);
  color: white;
  font-size: 0.7rem;
  font-weight: 700;
  display: flex; align-items: center; justify-content: center;
  margin-left: -10px;
}
.hero-trust-avatars span:first-child { margin-left: 0; }
.hero-trust p { color: rgba(255,255,255,0.7); font-size: 0.88rem; margin: 0; }
.hero-trust strong { color: var(--white); }

.hero-visual {
  display: flex;
  justify-content: center;
  align-items: center;
}

.dashboard-mockup {
  background: var(--white);
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 32px 80px rgba(0,0,0,0.4);
  width: 100%;
  max-width: 480px;
}

.mock-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--gray-100);
}

.mock-header h4 { font-size: 0.95rem; color: var(--dark); }
.mock-badge {
  background: #dcfce7;
  color: #166534;
  font-size: 0.72rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 100px;
}

.mock-schedule { display: flex; flex-direction: column; gap: 10px; }

.mock-shift {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  background: var(--gray-50);
  border-radius: var(--radius-sm);
}

.mock-avatar {
  width: 32px; height: 32px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 0.75rem; font-weight: 700; color: white; flex-shrink: 0;
}

.mock-shift-info { flex: 1; }
.mock-shift-info strong { font-size: 0.85rem; color: var(--dark); display: block; }
.mock-shift-info span { font-size: 0.75rem; color: var(--gray-500); }

.mock-time {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--primary);
  background: var(--primary-light);
  padding: 4px 10px;
  border-radius: 6px;
}

.mock-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-top: 20px; }
.mock-stat { text-align: center; padding: 12px; background: var(--gray-50); border-radius: var(--radius-sm); }
.mock-stat strong { display: block; font-size: 1.1rem; color: var(--dark); }
.mock-stat span { font-size: 0.72rem; color: var(--gray-500); }

/* ===== PAGE HERO (inner pages) ===== */
.page-hero {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  color: var(--white);
  padding: 80px 0;
  text-align: center;
}
.page-hero h1 { color: var(--white); margin-bottom: 16px; }
.page-hero p { color: rgba(255,255,255,0.8); font-size: 1.15rem; max-width: 560px; margin: 0 auto; }

/* ===== SECTIONS ===== */
section { padding: 96px 0; }

/* ===== FEATURES GRID ===== */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 32px;
}

.feature-card {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius);
  padding: 36px;
  transition: all var(--transition);
}
.feature-card:hover { border-color: var(--primary); box-shadow: var(--shadow); transform: translateY(-4px); }

.feature-icon {
  width: 56px; height: 56px;
  border-radius: var(--radius-sm);
  background: var(--primary-light);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;
}

.feature-card h3 { margin-bottom: 10px; font-size: 1.15rem; }
.feature-card p { font-size: 0.95rem; }

/* ===== HOW IT WORKS ===== */
.how-it-works { background: var(--gray-50); }

.steps-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 40px;
  position: relative;
}

.step {
  text-align: center;
  position: relative;
}

.step-number {
  width: 56px; height: 56px;
  background: var(--primary);
  color: var(--white);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.3rem;
  font-weight: 800;
  margin: 0 auto 20px;
}

.step h3 { margin-bottom: 10px; }
.step p { font-size: 0.95rem; }

/* ===== TESTIMONIALS ===== */
.testimonials { background: var(--white); }

.testimonial-carousel {
  position: relative;
  max-width: 720px;
  margin: 0 auto;
}

.testimonial-track { overflow: hidden; border-radius: var(--radius); }

.testimonial-slide {
  display: none;
  background: var(--gray-50);
  border-radius: var(--radius);
  padding: 48px;
  border-left: 4px solid var(--primary);
}
.testimonial-slide.active { display: block; }

.quote-icon { font-size: 3rem; color: var(--primary); opacity: 0.3; line-height: 1; margin-bottom: 16px; }

.testimonial-slide blockquote {
  font-size: 1.15rem;
  color: var(--gray-700);
  font-style: italic;
  line-height: 1.7;
  margin-bottom: 24px;
}

.testimonial-author { display: flex; align-items: center; gap: 16px; }
.testimonial-avatar {
  width: 48px; height: 48px; border-radius: 50%;
  background: var(--primary);
  color: white;
  display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: 1rem;
  flex-shrink: 0;
}
.testimonial-info strong { color: var(--dark); display: block; }
.testimonial-info span { font-size: 0.875rem; color: var(--gray-500); }

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
}

.carousel-btn {
  width: 44px; height: 44px;
  border: 2px solid var(--gray-300);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  color: var(--gray-700);
  transition: all var(--transition);
  font-size: 1.1rem;
}
.carousel-btn:hover { border-color: var(--primary); color: var(--primary); background: var(--primary-light); }

.carousel-dots { display: flex; gap: 8px; }
.carousel-dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--gray-300);
  transition: all var(--transition);
}
.carousel-dot.active { background: var(--primary); width: 24px; border-radius: 4px; }

/* ===== STATS ===== */
.stats-section { background: var(--primary); padding: 72px 0; }

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 48px;
  text-align: center;
}

.stat-item strong {
  display: block;
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--white);
  margin-bottom: 8px;
}

.stat-item p { color: rgba(255,255,255,0.75); font-size: 0.95rem; margin: 0; }

/* ===== PRICING TEASER ===== */
.pricing-teaser { background: var(--gray-50); }

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
  align-items: start;
}

.pricing-card {
  background: var(--white);
  border: 2px solid var(--gray-100);
  border-radius: var(--radius);
  padding: 36px;
  position: relative;
  transition: all var(--transition);
}

.pricing-card.featured {
  border-color: var(--primary);
  box-shadow: var(--shadow-lg);
  transform: scale(1.03);
}

.pricing-badge {
  position: absolute;
  top: -14px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--accent);
  color: white;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 5px 16px;
  border-radius: 100px;
  white-space: nowrap;
}

.pricing-tier { font-size: 0.85rem; font-weight: 700; color: var(--gray-500); text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 8px; }
.pricing-price { margin-bottom: 24px; }
.pricing-price strong { font-size: 2.8rem; font-weight: 800; color: var(--dark); }
.pricing-price sub { font-size: 1rem; color: var(--gray-500); font-weight: 400; }
.pricing-price .free-label { font-size: 2rem; font-weight: 800; color: var(--dark); }

.pricing-features { margin-bottom: 28px; }
.pricing-features li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 0;
  border-bottom: 1px solid var(--gray-100);
  font-size: 0.9rem;
  color: var(--gray-700);
}
.pricing-features li:last-child { border-bottom: none; }

.check { color: #16a34a; font-weight: 700; }
.dash { color: var(--gray-300); font-weight: 700; }

.pricing-card .btn { width: 100%; justify-content: center; }
.pricing-card .btn-primary { background: var(--primary); }
.pricing-card .btn-primary:hover { background: var(--primary-dark); box-shadow: 0 8px 24px rgba(0,81,195,0.3); }

/* ===== FULL PRICING TABLE ===== */
.billing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-bottom: 48px;
}

.billing-toggle span { font-weight: 600; color: var(--gray-700); font-size: 0.95rem; }
.billing-toggle span.active-label { color: var(--dark); }

.toggle-switch {
  position: relative;
  width: 52px;
  height: 28px;
  background: var(--gray-300);
  border-radius: 100px;
  cursor: pointer;
  transition: background var(--transition);
}
.toggle-switch.on { background: var(--primary); }
.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  background: var(--white);
  border-radius: 50%;
  transition: transform var(--transition);
  box-shadow: 0 2px 6px rgba(0,0,0,0.2);
}
.toggle-switch.on::after { transform: translateX(24px); }

.savings-badge {
  background: #dcfce7;
  color: #166534;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 100px;
}

.comparison-table-wrap { overflow-x: auto; }

.comparison-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  border: 1px solid var(--gray-100);
  border-radius: var(--radius);
  overflow: hidden;
}

.comparison-table th, .comparison-table td {
  padding: 16px 20px;
  text-align: center;
  border-bottom: 1px solid var(--gray-100);
}

.comparison-table th:first-child,
.comparison-table td:first-child { text-align: left; }

.comparison-table thead th {
  background: var(--gray-900);
  color: var(--white);
  font-size: 0.9rem;
  font-weight: 700;
}

.comparison-table thead th:first-child { background: var(--gray-900); }

.comparison-table .plan-head {
  font-size: 1.1rem;
  font-weight: 800;
}

.comparison-table .plan-price {
  font-size: 0.85rem;
  color: rgba(255,255,255,0.65);
  display: block;
  margin-top: 4px;
  font-weight: 400;
}

.comparison-table .plan-price.featured-price { color: #93c5fd; }

.comparison-table thead th.featured-col {
  background: var(--primary);
}

.comparison-table tbody tr:last-child td { border-bottom: none; }
.comparison-table tbody tr:nth-child(even) td { background: var(--gray-50); }

.comparison-table td .check { font-size: 1.1rem; }
.comparison-table td .dash { font-size: 1.1rem; }

.comparison-table .feature-name { font-weight: 500; color: var(--dark); font-size: 0.9rem; }
.comparison-table .feature-name small { display: block; color: var(--gray-500); font-weight: 400; font-size: 0.8rem; }

/* ===== FAQ ===== */
.faq-section { background: var(--gray-50); }

.faq-list { max-width: 720px; margin: 0 auto; }

.faq-item {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-sm);
  margin-bottom: 12px;
  overflow: hidden;
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--dark);
  text-align: left;
  transition: all var(--transition);
  background: none;
}
.faq-question:hover { background: var(--gray-50); }
.faq-question.open { color: var(--primary); }

.faq-icon { font-size: 1.3rem; color: var(--primary); transition: transform var(--transition); flex-shrink: 0; }
.faq-question.open .faq-icon { transform: rotate(45deg); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.3s ease;
  padding: 0 24px;
}
.faq-answer.open { max-height: 300px; padding: 0 24px 20px; }
.faq-answer p { font-size: 0.95rem; color: var(--gray-500); }

/* ===== CTA BLOCK ===== */
.cta-section {
  background: linear-gradient(135deg, var(--dark) 0%, var(--gray-900) 100%);
  padding: 100px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-section::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, rgba(0,81,195,0.3) 0%, transparent 70%);
  pointer-events: none;
}

.cta-section h2 { color: var(--white); position: relative; margin-bottom: 16px; }
.cta-section p { color: rgba(255,255,255,0.7); font-size: 1.1rem; position: relative; margin-bottom: 36px; max-width: 480px; margin-left: auto; margin-right: auto; }

.cta-actions { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; position: relative; }

/* ===== FEATURES PAGE ===== */
.feature-detail {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}

.feature-detail.reverse { direction: rtl; }
.feature-detail.reverse > * { direction: ltr; }

.feature-detail-text .section-label { margin-bottom: 16px; }
.feature-detail-text h2 { margin-bottom: 16px; }
.feature-detail-text p { margin-bottom: 24px; }

.feature-bullets { display: flex; flex-direction: column; gap: 12px; }
.feature-bullet {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  font-size: 0.95rem;
  color: var(--gray-700);
}
.feature-bullet-icon { width: 22px; height: 22px; background: #dcfce7; color: #16a34a; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 0.7rem; flex-shrink: 0; margin-top: 2px; font-weight: 800; }

.feature-detail-visual {
  background: var(--gray-50);
  border-radius: var(--radius);
  padding: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 340px;
}

.feature-illustration {
  width: 100%;
  max-width: 340px;
  background: var(--white);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
}

/* ===== INTEGRATIONS ===== */
.integrations-section { background: var(--gray-50); }

.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 28px;
}

.integration-category {
  background: var(--white);
  border-radius: var(--radius);
  padding: 28px;
  border: 1px solid var(--gray-100);
}

.integration-category h3 { font-size: 1rem; margin-bottom: 16px; color: var(--dark); }

.integration-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.integration-chip {
  background: var(--gray-50);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius-sm);
  padding: 6px 14px;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--gray-700);
}

/* ===== ABOUT PAGE ===== */
.mission-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}

.mission-text h2 { margin-bottom: 20px; }
.mission-text p { margin-bottom: 16px; }

.mission-visual {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  border-radius: var(--radius);
  padding: 48px;
  color: white;
  text-align: center;
}

.mission-visual .year { font-size: 4rem; font-weight: 800; display: block; }
.mission-visual .year-label { font-size: 0.9rem; opacity: 0.7; margin-bottom: 24px; display: block; }
.mission-values { display: flex; flex-direction: column; gap: 12px; }
.mission-value {
  background: rgba(255,255,255,0.1);
  border-radius: var(--radius-sm);
  padding: 12px 16px;
  font-weight: 600;
  font-size: 0.9rem;
}

.team-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 28px;
}

.team-card {
  text-align: center;
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius);
  padding: 36px 24px;
  transition: all var(--transition);
}
.team-card:hover { box-shadow: var(--shadow); transform: translateY(-4px); }

.team-avatar {
  width: 80px; height: 80px;
  border-radius: 50%;
  margin: 0 auto 16px;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.8rem;
  font-weight: 800;
  color: var(--white);
}

.team-card h3 { font-size: 1.1rem; margin-bottom: 4px; }
.team-card .role { font-size: 0.85rem; color: var(--primary); font-weight: 600; }

/* ===== CONTACT ===== */
.contact-grid {
  display: grid;
  grid-template-columns: 3fr 2fr;
  gap: 64px;
  align-items: start;
}

.contact-form-card {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius);
  padding: 48px;
  box-shadow: var(--shadow);
}

.form-group { margin-bottom: 20px; }

.form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }

label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--dark);
  margin-bottom: 8px;
}

input, select, textarea {
  width: 100%;
  padding: 12px 16px;
  border: 1.5px solid var(--gray-300);
  border-radius: var(--radius-sm);
  font-size: 0.95rem;
  font-family: inherit;
  color: var(--dark);
  transition: all var(--transition);
  background: var(--white);
  outline: none;
}

input:focus, select:focus, textarea:focus { border-color: var(--primary); box-shadow: 0 0 0 3px var(--primary-light); }

input.error, select.error, textarea.error { border-color: var(--accent); }
.error-msg { font-size: 0.8rem; color: var(--accent); margin-top: 4px; display: none; }
.error-msg.show { display: block; }

textarea { resize: vertical; min-height: 120px; }

.form-submit .btn { width: 100%; justify-content: center; }

.success-message {
  display: none;
  text-align: center;
  padding: 48px 24px;
}
.success-message.show { display: block; }
.success-icon { font-size: 3rem; margin-bottom: 16px; }
.success-message h3 { margin-bottom: 12px; }
.success-message p { font-size: 0.95rem; }

.contact-sidebar { display: flex; flex-direction: column; gap: 28px; }

.contact-info-card {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius);
  padding: 28px;
}
.contact-info-card h3 { font-size: 1rem; margin-bottom: 16px; }

.contact-item { display: flex; align-items: flex-start; gap: 12px; margin-bottom: 16px; }
.contact-item:last-child { margin-bottom: 0; }
.contact-item-icon { width: 36px; height: 36px; background: var(--primary-light); border-radius: var(--radius-sm); display: flex; align-items: center; justify-content: center; font-size: 1rem; flex-shrink: 0; }
.contact-item-text strong { display: block; font-size: 0.85rem; color: var(--dark); font-weight: 600; }
.contact-item-text span { font-size: 0.85rem; color: var(--gray-500); }

.locations-card {
  background: var(--white);
  border: 1px solid var(--gray-100);
  border-radius: var(--radius);
  padding: 28px;
}
.locations-card h3 { font-size: 1rem; margin-bottom: 16px; }
.location-item { padding: 12px 0; border-bottom: 1px solid var(--gray-100); font-size: 0.9rem; color: var(--gray-700); }
.location-item:last-child { border-bottom: none; }
.location-item strong { color: var(--dark); display: block; margin-bottom: 2px; }

/* ===== FOOTER ===== */
.site-footer {
  background: var(--dark);
  color: rgba(255,255,255,0.6);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}

.footer-brand { }
.footer-brand .nav-logo { color: white; margin-bottom: 16px; }
.footer-brand p { font-size: 0.88rem; line-height: 1.7; max-width: 240px; }

.footer-col h4 { color: var(--white); font-size: 0.85rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 16px; }
.footer-col ul { display: flex; flex-direction: column; gap: 10px; }
.footer-col ul a { font-size: 0.88rem; transition: color var(--transition); }
.footer-col ul a:hover { color: var(--white); }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.08);
  padding-top: 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  font-size: 0.85rem;
}

/* ===== UTILITY ===== */
.alt-bg { background: var(--gray-50); }
.text-center { text-align: center; }
.mt-8 { margin-top: 32px; }

/* ===== ANIMATIONS ===== */
.count-up { display: inline-block; }

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

.fade-up { animation: fadeUp 0.6s ease forwards; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .stats-grid { grid-template-columns: repeat(2, 1fr); gap: 32px; }
}

@media (max-width: 768px) {
  section { padding: 64px 0; }

  .nav-links, .nav-cta { display: none; }
  .hamburger { display: flex; }
  .mobile-nav { display: flex; }

  .hero { padding: 64px 0; }
  .hero-grid { grid-template-columns: 1fr; gap: 48px; }
  .hero-visual { display: none; }

  .page-hero { padding: 56px 0; }

  .features-grid { grid-template-columns: 1fr; }
  .steps-grid { grid-template-columns: 1fr 1fr; }

  .pricing-cards { grid-template-columns: 1fr; }
  .pricing-card.featured { transform: scale(1); }

  .feature-detail { grid-template-columns: 1fr; gap: 40px; }
  .feature-detail.reverse { direction: ltr; }
  .feature-detail-visual { display: none; }

  .mission-grid { grid-template-columns: 1fr; gap: 40px; }
  .mission-visual { display: none; }

  .team-grid { grid-template-columns: repeat(2, 1fr); }

  .contact-grid { grid-template-columns: 1fr; }
  .form-row { grid-template-columns: 1fr; }
  .contact-form-card { padding: 32px 24px; }

  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .footer-brand { grid-column: 1 / -1; }

  .stats-grid { grid-template-columns: repeat(2, 1fr); }

  .testimonial-slide { padding: 32px 24px; }

  .cta-section { padding: 72px 0; }

  .hero-trust { flex-wrap: wrap; }
}

@media (max-width: 480px) {
  .steps-grid { grid-template-columns: 1fr; }
  .team-grid { grid-template-columns: 1fr; }
